module Api
  class BaseController < ActionController::API
    private

    # ONE SHAPE FOR EVERY REFUSAL. The reference answers `{error,
    # message}` with the error's own name in it, and its test 13 reads
    # both, so the envelope is part of the API rather than a detail of
    # this implementation.
    def render_error(name, status, message)
      render json: { error: name, message: message }, status: status
    end
